answer:
#include <stdio.h>

char grade(int score) {
    if (score >= 90) {
        return 'A';
    } else if (score >= 70) {
        return 'B';
    } else if (score >= 50) {
        return 'C';
    }
    return 'D';
}

int main() {
    printf("%c\n", grade(85));
    return 0;
}

