#include <stdio.h>

int main() {
    int total = 0;
    int months = 0;
    // ここで while を使う
    printf("%d か月目に %d 円\n", months, total);
    return 0;
}

answer:
#include <stdio.h>

int main() {
    int total = 0;
    int months = 0;
    while (total < 20000) {
        total += 3000;
        months++;
    }
    printf("%d か月目に %d 円\n", months, total);
    return 0;
}

